INSERT INTO `remix_bazaar_line` (`guid`, `line`, `text`, `emote`, `reply_guid`, `reply`, `reply_emote`) VALUES
(7704011, 0, 'Every stall in this camp holds something history threw away. I only kept it.', 1, 0, '', 0),
(7704011, 1, 'Do not let the sands hurry you, champion. Here, at least, there is time.', 1, 0, '', 0),
(7704012, 0, 'Mind the hourglass. It runs in every direction at once, and it hates being bumped.', 25, 0, '', 0),
(7704012, 1, 'Every Timerunner who wakes here asks me the same thing first. The answer is no: you cannot go back yet.', 1, 0, '', 0),
(7704015, 0, 'Heirlooms! Gear that grows with you, for Timerunners with no time to shop twice.', 5, 0, '', 0),
(7704015, 1, 'Bronze only. Gold has no sense of history.', 1, 0, '', 0),
(7704015, 2, 'Moratari! Someone tried to pay me in Stratholme coin again.', 1, 7704012, 'Did you take it?', 6),
(7704016, 0, 'Roads fold best when nobody watches them do it.', 1, 0, '', 0),
(7704016, 1, 'Easy, girl. They are only Timerunners. They are always in a hurry.', 1, 0, '', 0),
(7704017, 0, 'Every dungeon in Northrend, waiting at the hour you are ready for it. Ask, and I will tell you which.', 1, 0, '', 0),
(7704018, 0, 'Valiance Keep, the first day... no, this page is smudged. Someone keeps changing things.', 6, 0, '', 0),
(7704018, 1, 'Every record says the same war. That is the comforting part. It is also the frightening part.', 1, 0, '', 0),
(7704019, 0, 'Power kept is power owed. Time always collects.', 1, 0, '', 0),
(7704013, 0, 'Stop watching the hourglass, sister. It will not run out.', 1, 7704014, 'It already has, in a hundred places. You just cannot hear it.', 1),
(7704013, 1, 'This year smells of plague and ice. I had forgotten. I had made myself forget.', 0, 0, '', 0),
(7704014, 0, 'When the bronze came for me, the Void was at the gates of Quel''Thalas. I hope they are still holding.', 1, 7704013, 'They will hold. Our people always hold, until the moment they do not.', 0),
(7704300, 0, 'The record is quieter today.', 1, 7704301, 'Quieter is not the same as whole, Andormu.', 1),
(7704201, 0, 'Proto-drakes, mammoths, a horse made entirely of bones. Every mount Northrend ever saw, and a few it only dreamed of.', 5, 0, '', 0),
(7704202, 0, 'Careful, that whelp bites. No, the other one.', 25, 0, '', 0),
(7704202, 1, 'Companions, keepsakes, toys. History remembers the battles. I remember what people carried into them.', 1, 0, '', 0),
(7704203, 0, 'Every blade on this rack came out of a dungeon in a braver hand than mine. It can go back in with yours.', 1, 0, '', 0),
(7704204, 0, 'Ten champions against the Scourge, again and again. Their spoils look better on you than in a tomb.', 1, 0, '', 0),
(7704205, 0, 'Twenty-five against the Lich King''s halls. This is what they carried home. The ones who came home.', 1, 0, '', 0),
(7704021, 0, 'Again. Shield up. No, the other shield.', 1, 0, '', 0),
(7704025, 0, 'You telegraph every swing, orc.', 1, 7704021, 'And you hide behind every tent. We all have our gifts.', 11),
(7704022, 0, 'The Light sounds the same in every year.', 1, 7704023, 'Says a man who has never heard it sung in Silvermoon.', 1),
(7704024, 0, 'Patience. The beast comes to the one who waits.', 0, 0, '', 0),
(7704026, 0, 'Breathe. The Light will wait for you. It always has.', 0, 0, '', 0),
(7704027, 0, 'I remember dying. It gets easier to talk about. Not much easier.', 1, 0, '', 0),
(7704028, 0, 'The winds here blow from tomorrow. Listen, and you will hear rain that has not fallen yet.', 1, 0, '', 0),
(7704029, 0, 'If you can see the fireball coming, you cast it too slowly.', 1, 0, '', 0),
(7704030, 0, 'Do not feed the imp. Whatever it tells you.', 274, 0, '', 0),
(7704031, 0, 'Even on stone, things grow. Slowly. Sideways, sometimes.', 0, 0, '', 0),
(7704501, 0, 'Last thing I remember, I was buying a round in Ironforge to toast the Lich King''s fall.', 1, 7704502, 'Then we had better be home before it goes flat.', 0),
(7704502, 0, 'Third time through the Borean Tundra this week. The penguins are starting to recognize me.', 11, 7704501, 'Those are not penguins taking notes, Vaela. Those are bronze dragons.', 1),
(7704503, 0, 'Gnome. Why is my bag lighter than when I came?', 6, 7704504, 'Time dilation! Or I borrowed your rations. One of the two.', 1),
(7704503, 1, 'I fought my way into Ulduar. Next to what was under it, the Scourge is almost polite.', 1, 7704504, 'Almost. They still bite.', 0),
(7704505, 0, 'The Sunwell burns again in this year. In mine too, and still half of Silvermoon lies in ruins. Some wounds take longer than a war.', 0, 0, '', 0),
(7704506, 0, 'They keep asking if I am from this year. I am barely from this century.', 1, 7704507, 'Ya worry too much, mon. Time be a river. We just be fishin''.', 11),
(7704507, 0, 'Vol''jin be chieftain of de Darkspear in dis year, and in mine. Some tings time don''t touch.', 1, 7704506, 'Do not say that too loud. The dragons get twitchy.', 0),
(7704508, 0, 'Best stew in any century. Do not tell the cook I said so.', 7, 7704509, 'I heard that, Steelhide. Second bowl is still Bronze.', 11),
(7704509, 0, 'Stew''s on! Crystalsong mushrooms, and something the gnome swears is a vegetable.', 5, 0, '', 0),
(7704509, 1, 'Eat while you can. The Scourge does not stop for supper.', 1, 0, '', 0),
(7704530, 0, 'Mind your feet! Crates of yesterday coming through!', 5, 0, '', 0),
(7704531, 0, 'Who orders forty hourglasses? Again?', 6, 0, '', 0),
(7704532, 0, 'If this crate is from tomorrow, why is it already late?', 1, 0, '', 0),
(7704533, 0, 'The Bazaar keeps its own peace, in every year.', 0, 0, '', 0),
(7704534, 0, 'No fighting, no thieving, and no meeting your own past self. Those are the rules.', 0, 0, '', 0);
